type View = 'Intake' | 'Case Desk' | 'Run Lab' | 'Investigations' | 'Evidence' | 'Sensors' | 'Reports' | 'Settings'
const AUDIT_KEY = 'pramaan.audit.v1'
const PREF_KEY = 'pramaan.preferences.v1'
const nav: { name: View; icon: React.ElementType; prototype?: boolean }[] = [
  { name: 'Intake', icon: ClipboardList }, { name: 'Case Desk', icon: LayoutDashboard }, { name: 'Run Lab', icon: Sparkles }, { name: 'Investigations', icon: FlaskConical },
  { name: 'Evidence', icon: FileCheck2 }, { name: 'Sensors', icon: Radio, prototype: true }, { name: 'Reports', icon: Archive }, { name: 'Settings', icon: Settings }
]
